import { sql, type Kysely } from 'kysely'

// Decision O-20 (search cost), technical part. Asset and person name searches matched
// strpos(wam.name_key(name), wam.name_key(q)): wam.name_key() ran for every row of the warehouse, about
// 10 µs each, so a search that matches nothing cost about 0.5 s of database time at 50,000 assets. The keys
// are now stored, generated by PostgreSQL from the same function (IMMUTABLE), so a search compares stored text
// and the result is unchanged by construction. Nothing else changes: no new privilege (wam_app already reads
// both tables; generated columns cannot be written), no new extension. A person's key is NULL exactly when the
// name is (erasure, PD-05), so erasing a person also removes the normalized name.
//
// Adding a stored column rewrites the table under ACCESS EXCLUSIVE (seconds at 50,000 rows); the migration
// CLI's lock timeout (WAM_MIGRATION_LOCK_TIMEOUT_MS) keeps it from queueing behind open transactions.

export const UP = String.raw`LOCK TABLE wam.assets, wam.persons IN ACCESS EXCLUSIVE MODE;
ALTER TABLE wam.assets ADD COLUMN name_key text COLLATE "C" GENERATED ALWAYS AS (wam.name_key(name)) STORED;
ALTER TABLE wam.persons ADD COLUMN display_name_key text COLLATE "C" GENERATED ALWAYS AS (wam.name_key(display_name)) STORED;
`

// Derived columns only: reverting loses nothing, so the down needs no guard.
export const DOWN = String.raw`LOCK TABLE wam.assets, wam.persons IN ACCESS EXCLUSIVE MODE;
ALTER TABLE wam.persons DROP COLUMN display_name_key;
ALTER TABLE wam.assets DROP COLUMN name_key;
`

export async function up(db: Kysely<unknown>): Promise<void> {
  await sql.raw(UP).execute(db)
}

export async function down(db: Kysely<unknown>): Promise<void> {
  await sql.raw(DOWN).execute(db)
}
